.photo-grid figure {
  margin: 0;
}

.photo-grid img {
  width: 100%;
  height: 180px;
  object-fit: cover;
  border-radius: 10px;
  cursor: zoom-in;
}

.photo-grid figcaption {
  margin-top: 6px;
